# -*- coding: utf-8 -*-
"""sci_topic_rec.py — 切入点推荐 + C1 报告 v0（Phase 1c）

输入：`projects/sci-assistant/topics/<slug>/landscape.json` + `gaps.json`
输出：同目录 `entry_points.json` + `report.md`

评分（权重见 `config.topic_rec.weights`）：
  可行性 = 0.45×空白机会 + 0.35×文献充分度 + 0.20×方向相关度
    空白机会 = 该子方向所有 gap 的最高 score（gaps.json）
    文献充分度 = log1p(篇数)/log1p(50)，封顶 1
    方向相关度 = 子方向篇数 / 候选总数

🔴 本工具**不生成领域结论**：推荐的"理由"只转述 gaps.json 的 reason 与 landscape 的
证据链接。它做的是排序与排版，不是判断——每条推荐都必须能点回 source 卡逐条核对。

用法：
  python tools/sci_topic_rec.py --topic 电解液设计
  python tools/sci_topic_rec.py --topic 电解液设计 --top 3 --json --no-write
  python tools/sci_topic_rec.py --selftest
"""

import argparse
import datetime
import json
import math
import os
import re
import sys

TOOLS_DIR = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, TOOLS_DIR)

import kb_lib as K  # noqa: E402
K.console_encoding()

CONFIG_REL = "projects/sci-assistant/config/sci_assistant_config.yaml"

TITLE_TMPL = {
    "comp-no-expt": "{sub}：用实验验证补齐纯计算结论",
    "single-lab-claim": "{sub}：独立复现与第三方验证",
    "synth-no-char": "{sub}：系统表征补全",
    "temporal-gap": "{sub}：重启低活跃高证据方向",
    "": "{sub}：深化现有证据链",
}

# 证据里剔除综述/公众号：它们可以解释背景，但不是"某子方向有实验/无实验"的直接证据
BAD_EVIDENCE_RE = re.compile(r"综述|[Mm]ini-?review|[Rr]eview|WeChat|公众号|微信")


# ---------------------------------------------------------------- 配置 / 输入

def load_config(path=None):
    import yaml
    p = path or os.path.join(K.VAULT, CONFIG_REL)
    with open(p, "r", encoding="utf-8") as f:
        return yaml.safe_load(f) or {}


def topic_dir(topic):
    if topic.endswith(".json"):
        return os.path.dirname(os.path.abspath(topic))
    return os.path.join(K.VAULT, "projects/sci-assistant/topics", topic)


def load_json(path):
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)


# ---------------------------------------------------------------- 评分（纯函数）

def literature_score(n, saturate=50):
    """文献充分度：log 饱和，50 篇封顶。"""
    if n <= 0:
        return 0.0
    return min(1.0, math.log1p(n) / math.log1p(saturate))


def feasibility_level(score, high, medium):
    if score >= high:
        return "high"
    if score >= medium:
        return "medium"
    return "low"


def compute_entries(land, gaps, cfg, top_n=None):
    """纯函数：landscape + gaps -> 排序后的切入点列表。"""
    tr = cfg.get("topic_rec") or {}
    weights = tr.get("weights") or {}
    w_gap = float(weights.get("gap", 0.45))
    w_lit = float(weights.get("literature", 0.35))
    w_rel = float(weights.get("relevance", 0.20))
    high = float(tr.get("feasibility_high", 0.55))
    med = float(tr.get("feasibility_medium", 0.35))
    max_reads = int(tr.get("max_suggested_reads", 10))
    top_n = int(top_n or tr.get("top_n", 5))

    subs = land.get("sub_directions") or []
    # 分母用候选集总数（子方向允许重叠，source_count 之和会大于候选数）
    total = int((land.get("kb_coverage") or {}).get("total_sources") or 0) \
        or sum(int(s.get("source_count") or 0) for s in subs) or 1
    gaps_by_sub = {}
    for g in (gaps.get("gaps") or []):
        gaps_by_sub.setdefault(g.get("sub_direction"), []).append(g)

    entries = []
    for s in subs:
        name = s.get("name")
        n = int(s.get("source_count") or 0)
        share = n / total
        gl = sorted(gaps_by_sub.get(name, []), key=lambda g: -float(g.get("score") or 0))
        gap_score = float(gl[0]["score"]) if gl else 0.0
        lit = literature_score(n)
        score = round(w_gap * gap_score + w_lit * lit + w_rel * share, 3)
        signal = gl[0]["signal"] if gl else ""
        title = TITLE_TMPL.get(signal, TITLE_TMPL[""]).format(sub=name)
        hits = int(gl[0]["hits"]) if gl else 0
        reads = min(max_reads, max(3, hits)) if gl else 3
        refs = []
        seen = set()

        def _add(r):
            n = r.get("name")
            if not n or n in seen or BAD_EVIDENCE_RE.search(n):
                return
            seen.add(n)
            refs.append(r)

        # 先放空白证据（已排除综述/公众号），再补该子方向的高分卡
        for g in gl:
            for r in (g.get("evidence_refs") or []):
                _add(r)
        for r in (s.get("key_papers") or []):
            _add(r)
        entries.append({
            "sub_direction": name,
            "title": title,
            "signal": signal or None,
            "source_count": n,
            "share": round(share, 3),
            "trend": s.get("trend"),
            "gap_score": round(gap_score, 3),
            "literature_score": round(lit, 3),
            "relevance": round(share, 3),
            "feasibility_score": score,
            "feasibility": feasibility_level(score, high, med),
            "rationale": gl[0]["reason"] if gl else
                         "该子方向暂无显著空白信号，但文献体量与证据强度支持继续推进",
            "suggested_reads": int(reads),
            "gaps": [{"signal": g["signal"], "hits": g["hits"],
                      "eligible": g["eligible"], "lift": g["lift"],
                      "score": g["score"]} for g in gl],
            "evidence_refs": [{"name": r["name"], "year": r.get("year")}
                              for r in refs[:10]],
        })
    entries.sort(key=lambda e: (-e["feasibility_score"], e["sub_direction"]))
    for i, e in enumerate(entries, 1):
        e["rank"] = i
    return entries[:top_n]


# ---------------------------------------------------------------- 报告

def _wikilink(name):
    return f"[[sources/{name}]]"


def render_report(land, gaps, entries, cfg, direction):
    cov = land.get("kb_coverage") or {}
    facets = land.get("facets") or {}
    anchor = ((land.get("signal") or {}).get("direction_anchor") or {})
    tiers = cov.get("tier_distribution") or {}
    tier_txt = " / ".join(f"{k} {v}" for k, v in tiers.items()) or "—"
    years = cov.get("time_range")
    year_txt = f"{years[0]}–{years[1]}" if years else "—"
    teams = facets.get("institution_teams") or []
    journals = facets.get("journal_norm") or {}
    j_top = sorted(journals.items(), key=lambda kv: -kv[1])[:5]
    base = (gaps.get("config") or {}).get("baseline_rates") or {}

    L = []
    L.append(f"# C1 切入点报告：{direction}")
    L.append("")
    L.append(f"> 生成于 {datetime.date.today().isoformat()} ｜ 输入：`landscape.json` + `gaps.json` "
             f"｜ 候选 {cov.get('total_sources')} 张 source 卡")
    L.append("> ⚠️ 本报告是**库内证据的机械化汇总**，不是领域判断。每条推荐都附证据链接，"
             "请逐条核对；gaps 的标记来自 ingest 批注，跨批次可能有风格差异。")
    L.append("")
    L.append("## 一、方向概况")
    L.append("")
    L.append(f"- **证据规模**：{cov.get('total_sources')} 张 source 卡，时间跨度 {year_txt}")
    L.append(f"- **方向锚定**：{'concept 页「' + anchor['page'] + '」' if anchor else '库内无同名概念页'}")
    L.append(f"- **期刊 tier**：{tier_txt}")
    L.append(f"- **主要期刊**：" + ("、".join(f"{k}（{v}）" for k, v in j_top) or "—"))
    L.append(f"- **团队（前 5）**：" + ("、".join(f"{t['name']}（{t['count']}）"
                                                for t in teams[:5]) or "—"))
    L.append("")
    L.append("## 二、子方向图谱")
    L.append("")
    L.append("| 子方向 | 篇数 | 占比 | 近两年占比 | 空白最高分 |")
    L.append("|---|---|---|---|---|")
    gaps_by_sub = {}
    for g in (gaps.get("gaps") or []):
        gaps_by_sub[g["sub_direction"]] = max(
            gaps_by_sub.get(g["sub_direction"], 0.0), float(g["score"]))
    for s in (land.get("sub_directions") or []):
        tr = s.get("trend") or {}
        rs = tr.get("recent_share")
        rs_txt = f"{rs:.0%}" if isinstance(rs, (int, float)) else "—"
        L.append(f"| {s['name']} | {s['source_count']} | {s['share']:.0%} | "
                 f"{rs_txt} | {gaps_by_sub.get(s['name'], 0):.2f} |")
    L.append("")
    L.append("> 子方向按 concept 出链分组，**允许重叠**（一篇可属多个方向），故篇数之和大于候选数。")
    L.append("")
    L.append("## 三、空白标注")
    L.append("")
    if gaps.get("gaps"):
        L.append("基线：" + "、".join(f"{k} {v:.1%}" for k, v in base.items()))
        L.append("")
        L.append("| 子方向 | 信号 | 命中/可计入 | 高出基线 | 机会 |")
        L.append("|---|---|---|---|---|")
        for g in gaps["gaps"]:
            L.append(f"| {g['sub_direction']} | `{g['signal']}` | {g['hits']}/{g['eligible']} | "
                     f"{g['lift']:+.0%} | {g['opportunity']} |")
        L.append("")
        for g in gaps["gaps"][:5]:
            refs = " ".join(_wikilink(r["name"]) for r in (g.get("evidence_refs") or [])[:3])
            L.append(f"- **{g['sub_direction']} × `{g['signal']}`**：{g['reason']}")
            L.append(f"  证据：{refs}")
    else:
        L.append("本方向未发现高出基线的空白信号。")
    L.append("")
    L.append("## 四、推荐切入点")
    L.append("")
    if not entries:
        L.append("（无可推荐切入点：子方向为空或全部低于阈值。）")
    for e in entries:
        L.append(f"### {e['rank']}. {e['title']}（可行性 {e['feasibility']}，"
                 f"综合 {e['feasibility_score']}）")
        L.append("")
        L.append(f"- **为什么是现在**：{e['rationale']}")
        L.append(f"- **可行性分解**：空白 {e['gap_score']} ｜ 文献充分度 {e['literature_score']} "
                 f"｜ 方向相关度 {e['relevance']}（篇数 {e['source_count']}）")
        if e.get("trend"):
            tr = e["trend"]
            L.append(f"- **时间趋势**：{tr.get('label')}（近两年占比 {tr.get('recent_share')}，"
                     f"跨度 {tr.get('span')}）")
        L.append(f"- **建议先读**：{e['suggested_reads']} 篇"
                 + (f"（围绕 `{e['signal']}` 判定是否成立）" if e["signal"] else ""))
        if e["evidence_refs"]:
            L.append("- **证据**：" + " ".join(_wikilink(r["name"])
                                              for r in e["evidence_refs"][:6]))
        L.append("- **下一步**：先核对上述证据卡的判定是真信号还是批注误差；"
                 "确认后按需补文献或设计最小验证实验。")
        L.append("")
    L.append("## 五、口径与局限")
    L.append("")
    L.append("1. 候选集来自 BM25 检索的前 "
             f"{cov.get('requested_top_k')} 张卡，**不是全库普查**——"
             "结论里的\"没有/很少\"仅指该候选集。")
    L.append("2. 空白判据是 lift（子方向命中率 − 全方向基线），依赖 source 卡上的"
             "批判性标记；标记由 ingest 时人工/AI 批注，跨批次可能有风格差异。")
    L.append("3. 年份分布偏向近年（库内 2026 年占多数），trend 只能作相对参考。")
    L.append("4. 可行性分是**排序用的启发式**（空白 0.45 / 文献 0.35 / 相关 0.20），"
             "不含实验室条件——`lab_profile.yaml` 填好后 P2.4 会把它接进来。")
    L.append("")
    L.append("## 六、下一步")
    L.append("")
    L.append("- 选定 1 个切入点 → 进 C2（实验方案推荐，Phase 2）。")
    L.append("- 若证据不足 → 用 `/lit-watch` 定向补该子方向文献，补完重跑本报告。")
    L.append("")
    return "\n".join(L)


def _link_exists(rel):
    p = os.path.join(K.VAULT, "wiki", rel + ("" if rel.endswith(".md") else ".md"))
    return os.path.isfile(p)


def validate_links(md, exists=None):
    """校验报告里的 `[[sources/…]]` 是否指向真实页面（exists 可注入，便于自检）。"""
    exists = exists or _link_exists
    broken = []
    for m in re.finditer(r"\[\[(sources/[^\]|]+)(?:\|[^\]]*)?\]\]", md):
        rel = m.group(1)
        if not exists(rel):
            broken.append(rel)
    return sorted(set(broken))


# ---------------------------------------------------------------- 自检

def _selftest():
    fails = []

    def chk(label, cond, detail=""):
        print(("  ok   " if cond else "  FAIL ") + label +
              (f"   [{detail}]" if detail and not cond else ""))
        if not cond:
            fails.append(label)

    cfg = {"topic_rec": {"top_n": 3, "weights": {"gap": 0.45, "literature": 0.35,
                                                "relevance": 0.2},
                         "feasibility_high": 0.55, "feasibility_medium": 0.35,
                         "max_suggested_reads": 10}}
    land = {
        "topic_id": "t", "query_direction": "测试方向",
        "kb_coverage": {"total_sources": 20, "requested_top_k": 20, "time_range": [2022, 2026],
                        "tier_distribution": {"T1": 12, "T3": 8}},
        "signal": {"direction_anchor": {"page": "测试方向", "type": "concept"}},
        "facets": {"institution_teams": [{"name": "A", "count": 3}],
                   "journal_norm": {"Nature": 5}},
        "sub_directions": [
            {"name": "S1", "source_count": 10, "share": 0.5,
             "trend": {"label": "rising", "recent_share": 0.8, "span": [2022, 2026]},
             "key_papers": [{"name": "p1", "year": "2026", "score": 1.0}]},
            {"name": "S2", "source_count": 7, "share": 0.35,
             "trend": {"label": "stable", "recent_share": 0.4, "span": [2021, 2026]},
             "key_papers": [{"name": "p2", "year": "2023", "score": 1.0}]},
            {"name": "S3", "source_count": 3, "share": 0.15,
             "trend": {"label": "rising", "recent_share": 1.0, "span": [2026, 2026]},
             "key_papers": []},
        ],
    }
    gaps = {
        "config": {"baseline_rates": {"comp-no-expt": 0.3}},
        "gaps": [
            {"sub_direction": "S1", "signal": "comp-no-expt", "hits": 5, "eligible": 10,
             "lift": 0.2, "score": 0.5, "opportunity": "high",
             "reason": "S1 中 5/10 篇命中 comp-no-expt；实验验证是空白",
             "evidence_refs": [{"name": "p1", "year": "2026"}]},
            {"sub_direction": "S2", "signal": "single-lab-claim", "hits": 3, "eligible": 7,
             "lift": 0.15, "score": 0.2, "opportunity": "low",
             "reason": "S2 中 3/7 篇命中 single-lab-claim",
             "evidence_refs": [{"name": "p2", "year": "2023"}]},
        ],
    }

    entries = compute_entries(land, gaps, cfg)
    chk("推荐：按综合分降序且截断 top_n", len(entries) == 3 and
        entries[0]["feasibility_score"] >= entries[1]["feasibility_score"])
    chk("推荐：S1 因空白分最高排第一", entries[0]["sub_direction"] == "S1")
    chk("推荐：标题按信号模板生成",
        entries[0]["title"] == "S1：用实验验证补齐纯计算结论")
    chk("推荐：无空白的 S3 用兜底标题", any(e["sub_direction"] == "S3" and "深化" in e["title"]
                                            for e in entries))
    chk("推荐：建议阅读篇数在 3..max 之间",
        all(3 <= e["suggested_reads"] <= 10 for e in entries))
    chk("推荐：文献充分度封顶 1", literature_score(500) == 1.0 and
        abs(literature_score(50) - 1.0) < 1e-9)
    chk("推荐：可行性分级", feasibility_level(0.6, 0.55, 0.35) == "high" and
        feasibility_level(0.4, 0.55, 0.35) == "medium" and
        feasibility_level(0.1, 0.55, 0.35) == "low")

    md = render_report(land, gaps, entries, cfg, "测试方向")
    chk("报告：含四个必需区块", all(h in md for h in
                                     ("## 一、方向概况", "## 二、子方向图谱",
                                      "## 三、空白标注", "## 四、推荐切入点")))
    chk("报告：证据链接为 wikilink", "[[sources/p1]]" in md)
    chk("报告：写明候选集不是全库普查", "不是全库普查" in md)

    fake_exists = lambda rel: rel in ("sources/p1", "sources/p2")  # noqa: E731
    broken = validate_links(md + "\n[[sources/definitely_missing_page]]",
                            exists=fake_exists)
    chk("链接校验：能抓到不存在的页面", broken == ["sources/definitely_missing_page"],
        str(broken))
    chk("链接校验：真实存在的链接不误报",
        validate_links("[[sources/p1]]", exists=fake_exists) == [])

    empty = compute_entries({"sub_directions": []}, {"gaps": []}, cfg)
    chk("空输入：返回空列表不崩", empty == [])

    print(f"SELFTEST {'PASSED' if not fails else 'FAILED'}: {len(fails)} failure(s)")
    return 0 if not fails else 1


# ---------------------------------------------------------------- 组装 / CLI

def build(topic, top_n=None, cfg=None):
    cfg = cfg or load_config()
    d = topic_dir(topic)
    lp, gp = os.path.join(d, "landscape.json"), os.path.join(d, "gaps.json")
    if not os.path.isfile(lp):
        raise SystemExit(f"[!] 缺少 {lp}")
    if not os.path.isfile(gp):
        raise SystemExit(f"[!] 缺少 {gp}；先跑 python tools/sci_gap_scan.py --topic \"{topic}\"")
    land, gaps = load_json(lp), load_json(gp)
    entries = compute_entries(land, gaps, cfg, top_n=top_n)
    md = render_report(land, gaps, entries, cfg, land.get("query_direction") or topic)
    return {
        "topic_id": land.get("topic_id"),
        "direction": land.get("query_direction"),
        "generated_at": datetime.date.today().isoformat(),
        "source_landscape": os.path.relpath(lp, K.VAULT).replace("\\", "/"),
        "source_gaps": os.path.relpath(gp, K.VAULT).replace("\\", "/"),
        "config": (cfg.get("topic_rec") or {}),
        "entry_points": entries,
        "report_markdown": md,
        "broken_links": validate_links(md),
    }


def main(argv=None):
    ap = argparse.ArgumentParser(description="C1 切入点推荐 + 报告（Phase 1c）")
    ap.add_argument("--topic", help="方向名或 landscape.json 路径")
    ap.add_argument("--top", type=int, default=None, help="推荐条数（默认取配置 5）")
    ap.add_argument("--json", action="store_true", help="结果 JSON 打印到 stdout（含 markdown）")
    ap.add_argument("--no-write", action="store_true", help="不写盘")
    ap.add_argument("--selftest", action="store_true", help="自检（不依赖知识库）")
    args = ap.parse_args(argv)

    if args.selftest:
        return _selftest()
    if not args.topic:
        ap.print_help()
        return 1

    data = build(args.topic, args.top)
    if args.json:
        print(json.dumps(data, ensure_ascii=False, indent=2))
    if not args.no_write:
        d = topic_dir(args.topic)
        ep_path = os.path.join(d, "entry_points.json")
        md_path = os.path.join(d, "report.md")
        with open(ep_path, "w", encoding="utf-8", newline="\n") as f:
            f.write(json.dumps({k: v for k, v in data.items() if k != "report_markdown"},
                               ensure_ascii=False, indent=2) + "\n")
        with open(md_path, "w", encoding="utf-8", newline="\n") as f:
            f.write(data["report_markdown"] + "\n")
        # 写后复算
        with open(md_path, encoding="utf-8") as f:
            back = f.read()
        if "## 四、推荐切入点" not in back:
            raise SystemExit(f"[!] 报告写盘复算失败: {md_path}")
        print(f"[ok] {data['direction']}：{len(data['entry_points'])} 个切入点")
        for e in data["entry_points"]:
            print(f"     {e['rank']}. [{e['feasibility']}] {e['title']}")
        if data["broken_links"]:
            print(f"[!] 断链 {len(data['broken_links'])}: {data['broken_links'][:5]}")
        print(f"     输出: {os.path.relpath(md_path, K.VAULT)} / entry_points.json")
    return 0


if __name__ == "__main__":
    sys.exit(main())
